$ErrorActionPreference='Stop'
$root=Split-Path -Parent $PSScriptRoot;$executor=Join-Path $root 'executor.ps1';$functional='C:\flcad_mobile';$head=(git -C $functional rev-parse HEAD).Trim();$tmp=Join-Path $env:TEMP ('flcad-cad-diagnosis-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Force $tmp|Out-Null
function W($p,$v){$v|ConvertTo-Json -Depth 10|Set-Content -LiteralPath $p -Encoding UTF8};function A([bool]$c,[string]$m){if(!$c){throw "ASSERTION FAILED: $m"}}
try {
  $base=[ordered]@{schemaVersion='1.0';id='AB08A-DIAG-VALID';objective='fixed diagnosis';sourceBranch='feat/plane-axis-intersection-point';baseCommit=$head;allowedPaths=@('lib','test','test_assets/real_meshes/PARCIAL_FURO_18MM.stl','windows');requiredTests=@('source inspection');acceptanceCriteria=@('diagnosis report');limits=@{maxDurationSeconds=300;maxOutputBytes=1048576};permissions=@{workspaceWrite=$false;network=$false;gitMutation=$false;remotePublish=$false};state='approved';reportPath='reports/AB08A-DIAG-VALID.json';action='cad-convergence-diagnosis'};$p=Join-Path $tmp 'valid.json';W $p $base;& powershell -NoProfile -File $executor -Task $p -Worktree $functional -ReportRoot $tmp -ValidateOnly|Out-Null;A($LASTEXITCODE -eq 0)'valid diagnostic task must validate'
