  $bad=@{};foreach($x in $base.GetEnumerator()){$bad[$x.Key]=$x.Value};$bad.sourceBranch='automation/flcad-bridge';$p=Join-Path $tmp 'bad-branch.json';W $p $bad;$old=$ErrorActionPreference;$ErrorActionPreference='Continue';& powershell -NoProfile -File $executor -Task $p -Worktree $functional -ReportRoot $tmp -ValidateOnly 2>&1|Out-Null;$code=$LASTEXITCODE;$ErrorActionPreference=$old;A($code -ne 0)'wrong branch must reject'
  Write-Output 'cad-diagnosis.tests.ps1: PASS'
